function bodyweightGroup(category='',target=''){
  const s=(String(category)+' '+String(target)).toLowerCase();
  if(s.includes('chest')||s.includes('pectoral'))return 'push';
  if(s.includes('upper leg')||s.includes('lower leg')||s.includes('quad')||s.includes('glute')||s.includes('hamstring')||s.includes('calf'))return 'legs';
  if(s.includes('waist')||s.includes('abdom')||s.includes('core')||s.includes('oblique'))return 'core';
  if(s.includes('back')||s.includes('lat')||s.includes('spine'))return 'back';
  if(s.includes('shoulder')||s.includes('upper arm')||s.includes('lower arm')||s.includes('bicep')||s.includes('tricep')||s.includes('forearm'))return 'upper';
  if(s.includes('cardio'))return 'cardio';
  return 'other';
}
function bodyweightMuscles(category='',target='',secondary=[]){
  const s=(String(category)+' '+String(target)+' '+(secondary||[]).join(' ')).toLowerCase(),out=[];
  const add=x=>{if(!out.includes(x))out.push(x)};
  if(s.includes('chest')||s.includes('pectoral'))add('chest'); if(s.includes('tricep'))add('triceps'); if(s.includes('bicep'))add('biceps');
  if(s.includes('shoulder')||s.includes('deltoid'))add('shoulders'); if(s.includes('back')||s.includes('lat')||s.includes('spine'))add('back');
  if(s.includes('glute'))add('glutes'); if(s.includes('hamstring'))add('hamstrings'); if(s.includes('quad')||s.includes('upper leg'))add('quads');
  if(s.includes('calf')||s.includes('lower leg'))add('calves'); if(s.includes('waist')||s.includes('abdom')||s.includes('core')||s.includes('oblique'))add('abs');
  if(s.includes('forearm')||s.includes('lower arm'))add('forearms'); if(!out.length)add('abs'); return out.slice(0,4);
}
function instructionTextParts(x){
  const out=[];
  const push=v=>{if(typeof v==='string'&&v.trim())out.push(v.trim());else if(Array.isArray(v))v.forEach(push);else if(v&&typeof v==='object')Object.values(v).forEach(push)};
  push(x?.instructions);
  push(x?.instruction_steps);
  return out;
}
function preferredInstruction(x){
  const ko=x?.instructions?.ko; if(typeof ko==='string'&&ko.trim())return ko.trim();
  const koSteps=x?.instruction_steps?.ko; if(Array.isArray(koSteps)&&koSteps.length)return koSteps.filter(Boolean).join(' ');
  const en=x?.instructions?.en; if(typeof en==='string'&&en.trim())return en.trim();
  const enSteps=x?.instruction_steps?.en; if(Array.isArray(enSteps)&&enSteps.length)return enSteps.filter(Boolean).join(' ');
  return instructionTextParts(x)[0]||'동작을 천천히 정확한 자세로 수행합니다.';
}
// V1.4.9-equivalent safety filter: ExerciseDB may label exercises as "body weight"
// even when a bar, bench, wall, rings or another fixed structure is required.
function isHomeCompatibleExercise(x){
  const equipment=String(x?.equipment||'').trim().toLowerCase();
  if(equipment && equipment!=='body weight' && equipment!=='bodyweight')return false;
  const text=[x?.name,x?.body_part,x?.target,...instructionTextParts(x)].flat().filter(Boolean).join(' ').toLowerCase();
  const forbidden=[
    /pull[ -]?up/,/chin[ -]?up/,/hanging|\bhang\b/,/inverted row|horizontal row/,/\bdips?\b/,
    /bench/,/wall/,/door/,/anchor/,/rack/,/parallel bar/,/\bbar\b/,/rings?/,/rope/,/trx|suspension/,
    /machine/,/cable/,/smith/,/leverage/,/sled/,/bosu/,/medicine ball/,/stability ball/,/swiss ball/,
    /dumbbell/,/barbell/,/ez bar/,/kettlebell/,/roller/,/platform/,/box jump|plyo box/,/captain['’]?s chair/
  ];
  return !forbidden.some(rx=>rx.test(text));
}
function normalizeBodyweightExercises(records,limit=100){
  const out=[]; for(const x of Array.isArray(records)?records:[]){
    if(!isHomeCompatibleExercise(x))continue;
    const gifPath=String(x?.gif_url||x?.gifPath||'').replace(/^\/+/, '');
    if(!/^videos\/[0-9A-Za-z_-]+\.gif$/i.test(gifPath))continue;
    const category=String(x?.body_part||x?.category||'other'), target=String(x?.target||'');
    const mediaMatch=gifPath.match(/-([0-9A-Za-z]+)\.gif$/i);
    const id='bw-'+String(x?.id||mediaMatch?.[1]||out.length+1);
    out.push({id,exerciseId:String(x?.media_id||mediaMatch?.[1]||x?.id||''),name:String(x?.name||'Bodyweight exercise'),equipment:'bodyweight',animation:'bodyweight',gifPath,category,group:bodyweightGroup(category,target),muscles:bodyweightMuscles(category,target,x?.secondary_muscles),view:String(category).toLowerCase().includes('back')?'back':'front',sets:3,reps:10,maxReps:24,rest:35,cue:preferredInstruction(x)});
    if(out.length>=limit)break;
  } return out;
}
function buildFallbackExerciseLibrary(){
  const allowed=new Set(['bodyweight','body weight','kettlebell','band','chair']);
  const out=[],seen=new Set();
  for(const day of Object.values(WORKOUT_LIBRARY)){
    for(const ex of day?.exercises||[]){
      if(!ex||ex.durationMinutes||seen.has(ex.id))continue;
      const equipment=String(ex.equipment||'bodyweight').toLowerCase();
      if(!allowed.has(equipment))continue;
      const media=CURATED_EXERCISE_MEDIA[ex.animation];
      if(!media?.gifPath)continue;
      const mediaEquip=(media.equipments||[]).map(v=>String(v).toLowerCase());
      const equipOk=(equipment==='bodyweight'||equipment==='body weight')?mediaEquip.some(v=>v==='body weight'||v==='bodyweight'):mediaEquip.includes(equipment);
      if(!equipOk)continue;
      seen.add(ex.id);
      const category=day.title||'홈트';
      out.push({...ex,exerciseId:media.exerciseId||ex.id,gifPath:media.gifPath,category,group:bodyweightGroup(category,media.targetMuscles?.[0]||ex.name),muscles:[...(media.targetMuscles||[]),...(media.secondaryMuscles||[])].slice(0,4),view:String(category).includes('등')?'back':'front'});
    }
  }
  return out;
}
function seededNumber(seed){let h=2166136261;for(const c of String(seed)){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function seededShuffle(arr,seed){const a=[...arr],rnd=seededNumber(seed);for(let i=a.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function estimatedExerciseSeconds(p){return (p.sets*p.reps*3)+(Math.max(0,p.sets-1)*p.rest)}
function generateAutoWorkoutLocal(pool,intensity='normal',seed=''){
  const p=intensityProfiles[intensity]||intensityProfiles.normal;
  const safe=(Array.isArray(pool)?pool:[]).filter(x=>x&&['bodyweight','body weight','kettlebell','band','chair'].includes(String(x.equipment||'bodyweight').toLowerCase()));
  if(safe.length<6)return {intensity:p.id||intensity,targetMinutes:p.targetMinutes,estimatedMinutes:0,exercises:[]};
  const per=estimatedExerciseSeconds(p),maxCount=Math.min(14,safe.length);let count=6,best=Infinity;
  for(let n=6;n<=maxCount;n++){const mins=per*n/60;if(mins<25||mins>30)continue;const d=Math.abs(mins-p.targetMinutes);if(d<best){best=d;count=n}}
  if(best===Infinity)count=Math.max(6,Math.min(maxCount,Math.round((p.targetMinutes*60)/per)));
  const groups={};for(const ex of safe){const g=ex.group||bodyweightGroup(ex.category,ex.name);(groups[g]??=[]).push(ex)}
  for(const k of Object.keys(groups))groups[k]=seededShuffle(groups[k],String(seed)+':'+intensity+':'+k);
  const order=['push','legs','core','back','upper','cardio','other'],selected=[],used=new Set();let round=0;
  while(selected.length<count&&round<100){for(const g of order){const ex=(groups[g]||[]).shift();if(ex&&!used.has(ex.id)){selected.push(ex);used.add(ex.id);if(selected.length>=count)break}}round++}
  if(selected.length<count){for(const ex of seededShuffle(safe,String(seed)+':fill')){if(!used.has(ex.id)){selected.push(ex);used.add(ex.id);if(selected.length>=count)break}}}
  const exercises=selected.map(ex=>({...ex,sets:p.sets,reps:p.reps,maxReps:Math.max(Number(ex.maxReps||0),p.reps+8),rest:p.rest,tempo:intensity==='pre'?'slow':((intensity==='burning'||intensity==='extreame')?'fast':'normal'),intensity}));
  const planSeconds=()=>exercises.reduce((sum,ex)=>sum+((ex.sets*ex.reps*3)+(Math.max(0,ex.sets-1)*ex.rest)),0);
  let guard=0;
  while(planSeconds()<25*60&&guard<exercises.length*3){const ex=exercises[guard%exercises.length];if(ex.sets<5)ex.sets++;guard++}
  return {intensity,targetMinutes:p.targetMinutes,estimatedMinutes:Math.round((planSeconds()/60)*10)/10,exercises};
}
async function loadBodyweightCatalog(){
  const fallback=buildFallbackExerciseLibrary();
  if(fallback.length>=6){bodyweightLibrary=fallback;renderWorkoutBuilder();}
  const cached=localStorage.getItem(BODYWEIGHT_CACHE_KEY);
  if(cached){try{const parsed=JSON.parse(cached);if(Array.isArray(parsed)&&parsed.length>=6){bodyweightLibrary=parsed;renderWorkoutBuilder();}}catch(_){}}
  try{
    const r=await fetch(BODYWEIGHT_CATALOG_URL,{cache:'no-store'});
    if(!r.ok)throw new Error('catalog '+r.status);
    const records=await r.json();
    const remote=normalizeBodyweightExercises(records,100);
    if(remote.length>=6){
      const merged=[...fallback,...remote].filter((ex,i,arr)=>arr.findIndex(v=>v.id===ex.id)===i);
      bodyweightLibrary=merged;
      localStorage.setItem(BODYWEIGHT_CACHE_KEY,JSON.stringify(merged));
      renderWorkoutBuilder();
    }
  }catch(e){console.warn('home exercise catalog',e)}
}
