const defaultMotions=Object.fromEntries(Object.keys(motionCatalog).map(k=>[k,{rev:0}]));
function ensureMotionSettings(){state.motions=state.motions||{};for(const [k,v] of Object.entries(defaultMotions))state.motions[k]={...v,...(state.motions[k]||{})};state.workoutPlans=state.workoutPlans||{};state.progression=state.progression||{};state.completions=state.completions||{};state.history=state.history||[]}
function ensureWorkoutConfig(){const old=state.workoutConfig||{};const intensity=intensityProfiles[old.intensity]?old.intensity:'normal';state.workoutConfig={mode:['default','custom','auto'].includes(old.mode)?old.mode:'default',intensity,targetMinutes:intensityProfiles[intensity].targetMinutes,customRoutine:Array.isArray(old.customRoutine)?old.customRoutine:[],autoRoutine:Array.isArray(old.autoRoutine)?old.autoRoutine:[],autoEstimatedMinutes:Number(old.autoEstimatedMinutes||0),routineVersion:Number(old.routineVersion||0)}}
function parseGifLoopSeconds(buffer){const b=new Uint8Array(buffer);let total=0,frames=0;for(let i=0;i+7<b.length;i++){if(b[i]===0x21&&b[i+1]===0xF9&&b[i+2]===0x04){const delay=b[i+4]|(b[i+5]<<8);if(delay>0){total+=Math.max(2,delay)*.01;frames++}}}if(!frames||!Number.isFinite(total)||total<.6||total>12)return 3;return Math.round(total*100)/100}
function muscleMapUrl(key,exercise=null){const base=motionCatalog[key]||motionCatalog.pushup;const muscles=(exercise?.muscles?.length?exercise.muscles:base.muscles)||['chest'];const view=exercise?.view||base.view||'front';const layers='E53935:'+muscles.join(',');return 'https://api.anatome.dev/generateImage?gender=male&view='+encodeURIComponent(view)+'&layers='+encodeURIComponent(layers)+'&output=raw'}
function applyTheme(id){const t=themePresets.find(x=>x.id===id)||themePresets[0];const r=document.documentElement.style;r.setProperty('--teal',t.strong);r.setProperty('--teal2',t.soft);r.setProperty('--bg',t.bg);r.setProperty('--line',t.line);document.querySelector('meta[name=theme-color]')?.setAttribute('content',t.strong)}
const clone=o=>JSON.parse(JSON.stringify(o));
const pad=n=>String(n).padStart(2,'0');
const localDate=(d=new Date())=>{const f=new Intl.DateTimeFormat('en-CA',{timeZone:state?.settings?.timezone||'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'});return f.format(d)};
const weekKey=(d=new Date())=>{const x=new Date(d);const day=(x.getDay()+6)%7;x.setDate(x.getDate()-day);return localDate(x)};
function variantTitle(task,day){if(task.id==='workout-weekday'){const k=weekdayKeys[day];return (workoutLibrary[k]?.title||'운동')+' 운동';}return task.variants?.[day]||task.title}
function currentTasks(date=new Date()){const day=date.getDay();return state.tasks.filter(t=>t.days.includes(day)).sort((a,b)=>a.start.localeCompare(b.start)).map(t=>({...t,displayTitle:variantTitle(t,day)}))}
function isDone(taskId,date=localDate()){return !!state.completions?.[date]?.[taskId]}
async function saveState(){state.updatedAt=new Date().toISOString();state.version=APP_VERSION;localStorage.setItem(LOCAL_STORAGE_KEY,JSON.stringify(state));const status=$('#serverStatus');if(status)status.innerHTML='<span class="statusDot ok"></span>로컬 저장 정상';return true}
async function load(){const legacy=localStorage.getItem(LOCAL_STORAGE_KEY)||localStorage.getItem('daily-routine')||localStorage.getItem('cotec-daily-routine');state=legacy?JSON.parse(legacy):clone(DEFAULT_STATE);workoutLibrary=clone(WORKOUT_LIBRARY);state.settings=state.settings||{};if(!state.settings.theme)state.settings.theme='mint';if(![7,30,90].includes(Number(state.settings.achievementRange)))state.settings.achievementRange=30;state.version=APP_VERSION;ensureMotionSettings();ensureWorkoutConfig();applyTheme(state.settings.theme);renderAll();await initPushStatus();handleDeepLink();loadBodyweightCatalog();startLocalNotificationWatcher();await saveState()}
function switchView(v){$$('.view').forEach(x=>x.classList.toggle('active',x.id===v));$$('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));if(v==='workout')prepareWorkout();}
$$('#nav button').forEach(b=>b.onclick=()=>switchView(b.dataset.view));
function markDone(task,date=localDate(),value=true){state.completions[date]=state.completions[date]||{};state.completions[date][task.id]=value;if(value)state.history.unshift({type:'task',taskId:task.id,title:task.displayTitle||task.title,date,at:new Date().toISOString()});saveState();renderToday();renderHistory()}
function currentLocalMinutes(){const f=new Intl.DateTimeFormat('en-GB',{timeZone:state?.settings?.timezone||'Asia/Seoul',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const p=Object.fromEntries(f.formatToParts(new Date()).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));return Number(p.hour)*60+Number(p.minute)}
function taskMissedClient(t,done){const end=t.end||t.start;if(done||!end)return false;const [h,m]=end.split(':').map(Number);return currentLocalMinutes()>(h*60+m)}
function getAchievementSeries(days=30){const base=new Date();base.setHours(0,0,0,0);const arr=[];for(let i=days-1;i>=0;i--){const d=new Date(base);d.setDate(base.getDate()-i);const dateKey=localDate(d);const tasks=currentTasks(d);const total=tasks.length;const done=tasks.filter(t=>!!state.completions?.[dateKey]?.[t.id]).length;const rate=total?Math.round(done/total*100):0;arr.push({dateKey,date:new Date(d),label:(d.getMonth()+1)+'/'+d.getDate(),weekday:weekdayKo[d.getDay()],total,done,rate});}return arr}
function buildSmoothChartPath(points){if(!points.length)return '';if(points.length===1)return 'M '+points[0].x+' '+points[0].y;let d='M '+points[0].x+' '+points[0].y;for(let i=0;i<points.length-1;i++){const p=points[i],n=points[i+1];const mx=(p.x+n.x)/2;d+=' Q '+p.x+' '+p.y+' '+mx+' '+((p.y+n.y)/2);if(i===points.length-2)d+=' T '+n.x+' '+n.y}return d}
function currentGoalStreak(series,threshold=90){let streak=0;for(let i=series.length-1;i>=0;i--){const item=series[i];if(!item.total)continue;if(item.rate>=threshold)streak++;else break}return streak}
function setAchievementDetail(item){if(!item||!$('#achievementDetail'))return;achievementFocusKey=item.dateKey;$('#achievementDetail').innerHTML='<b>'+item.dateKey+' ('+item.weekday+')</b><br>달성율 <b>'+item.rate+'%</b> · 완료 '+item.done+'개 / 예정 '+item.total+'개';$$('.chartDot').forEach(dot=>dot.classList.toggle('active',dot.dataset.key===item.dateKey))}
function renderAchievementChart(){const root=$('#achievementChart');if(!root)return;const selectedDays=[7,30,90].includes(Number(state.settings?.achievementRange))?Number(state.settings.achievementRange):30;state.settings.achievementRange=selectedDays;$$('.rangeBtn').forEach(btn=>{const active=Number(btn.dataset.days)===selectedDays;btn.classList.toggle('active',active);btn.onclick=()=>{const days=Number(btn.dataset.days);if(![7,30,90].includes(days)||days===Number(state.settings.achievementRange))return;state.settings.achievementRange=days;achievementFocusKey=null;renderHistory();saveState()}});const series=getAchievementSeries(selectedDays);const today=series[series.length-1]||{rate:0};const active=series.find(x=>x.dateKey===achievementFocusKey)||today||series[0];const average=Math.round((series.reduce((s,x)=>s+x.rate,0)/(series.length||1))||0);const best=series.reduce((a,b)=>!a||b.rate>a.rate?b:a,null);const eligible=series.filter(x=>x.total>0);const goalDays=eligible.filter(x=>x.rate>=90).length;const streak=currentGoalStreak(getAchievementSeries(90),90);$('#achTodayRate').textContent=(today?.rate||0)+'%';$('#achWeekAvg').textContent=average+'%';$('#achBestRate').textContent=((best?.rate)||0)+'%';$('#achGoalDays').textContent=goalDays+'/'+eligible.length+'일';$('#achStreak').textContent=streak+'일';if(!series.length){root.innerHTML='<div class="emptyChart">표시할 데이터가 없습니다.</div>';$('#achievementDetail').textContent='선택 기간 달성율을 표시합니다.';return}const width=760,height=250,padL=34,padR=18,padT=18,padB=32,plotW=width-padL-padR,plotH=height-padT-padB;const points=series.map((item,i)=>({item,x:padL+(plotW*(series.length===1?0:i/(series.length-1))),y:padT+plotH-((item.rate||0)/100)*plotH}));const linePath=buildSmoothChartPath(points);const areaPath=linePath?linePath+' L '+points[points.length-1].x+' '+(padT+plotH)+' L '+points[0].x+' '+(padT+plotH)+' Z':'';const yGuides=[0,25,50,75,100].map(v=>'<line class="chartGrid" x1="'+padL+'" y1="'+(padT+plotH-(v/100)*plotH)+'" x2="'+(width-padR)+'" y2="'+(padT+plotH-(v/100)*plotH)+'"></line><text class="chartAxisText" x="4" y="'+(padT+plotH-(v/100)*plotH+4)+'">'+v+'%</text>').join('');const goalY=padT+plotH-(.9*plotH);const goalLine='<line class="chartGoalLine" x1="'+padL+'" y1="'+goalY+'" x2="'+(width-padR)+'" y2="'+goalY+'"></line><text class="chartGoalText" text-anchor="end" x="'+(width-padR)+'" y="'+(goalY-6)+'">목표 90%</text>';const labelStep=selectedDays<=7?1:(selectedDays<=30?5:15);const xLabels=series.map((item,i)=>{if(!(i===0||i===series.length-1||i%labelStep===0))return '';return '<text class="chartAxisText" text-anchor="middle" x="'+points[i].x+'" y="'+(height-8)+'">'+item.label+'</text>'}).join('');const dotR=selectedDays>=90?3.2:(selectedDays>=30?4.2:5.2);const dots=points.map(p=>'<circle class="chartDot'+((active&&active.dateKey===p.item.dateKey)?' active':'')+'" data-key="'+p.item.dateKey+'" cx="'+p.x+'" cy="'+p.y+'" r="'+dotR+'"></circle>').join('');root.innerHTML='<svg class="chartSvg" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="최근 '+selectedDays+'일 달성율 그래프">'+yGuides+goalLine+'<path class="chartArea" d="'+areaPath+'"></path><path class="chartPath" d="'+linePath+'"></path>'+dots+xLabels+'</svg>';$$('.chartDot').forEach(dot=>dot.onclick=()=>{const item=series.find(x=>x.dateKey===dot.dataset.key);setAchievementDetail(item)});setAchievementDetail(active)}
function renderToday(){const day=new Date().getDay(),date=localDate(),tasks=currentTasks();const done=tasks.filter(t=>isDone(t.id,date)).length;$('#todayTitle').textContent='오늘 · '+weekdayKo[day]+'요일';$('#todaySub').textContent=date;$('#todayRate').textContent=(tasks.length?Math.round(done/tasks.length*100):0)+'%';$('#todayDone').textContent=done;$('#todayRemain').textContent=tasks.length-done;$('#todayList').innerHTML=tasks.map(t=>{const done=isDone(t.id,date),missed=taskMissedClient(t,done),simpleComplete=t.id==='saturday-run';const check='<button class="check '+(done?'on':'')+' taskCheck" data-id="'+t.id+'" aria-label="완료 체크">'+(done?'✓':'')+'</button>';const action=t.category==='workout'&&!simpleComplete?'<div class="workoutActions"><button class="btn primary workoutOpen" data-id="'+t.id+'">운동 시작</button>'+check+'</div>':check;return '<div class="todo '+(done?'done':'')+(missed?' missed':'')+'"><div class="time">'+t.start+'</div><div class="tmain"><b>'+t.displayTitle+'</b><small>'+t.end+' · '+labelCategory(t.category)+'</small></div>'+action+'</div>'}).join('');$$('.taskCheck').forEach(b=>b.onclick=()=>{const t=tasks.find(x=>x.id===b.dataset.id);markDone(t,date,!isDone(t.id,date))});$$('.workoutOpen').forEach(b=>b.onclick=()=>{switchView('workout');prepareWorkout(true)});}
function labelCategory(c){return {workout:'운동',study:'역량강화',work:'업무',english:'영어',routine:'루틴'}[c]||c}
function renderWeek(){const days=[1,2,3,4,5,6,0];$('#weekGrid').innerHTML=days.map(d=>{const items=state.tasks.filter(t=>t.days.includes(d)).sort((a,b)=>a.start.localeCompare(b.start));return '<div class="daycard"><h3>'+weekdayKo[d]+'요일</h3>'+items.map(t=>'<div class="dayitem"><b>'+t.start+' '+variantTitle(t,d)+'</b><span>'+t.end+'</span></div>').join('')+'</div>'}).join('')}
function renderHistory(){renderAchievementChart();const arr=state.history||[];const historyRoot=$('#historyList');if(historyRoot)historyRoot.innerHTML=arr.length?arr.slice(0,80).map(h=>'<div class="historyItem"><b>'+escapeHtml(h.title||h.type)+'</b><small>'+h.date+' · '+new Date(h.at||Date.now()).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})+'</small></div>').join(''):'<div class="empty">아직 기록이 없습니다.</div>'}
function exerciseForIntensity(ex,intensity){const p=intensityProfiles[intensity]||intensityProfiles.normal;return {...clone(ex),sets:p.sets,reps:p.reps,maxReps:Math.max(Number(ex.maxReps||0),p.reps+8),rest:p.rest,intensity:p.id}}
function renderRoutineItems(target,list,removable=false){const el=$(target);if(!el)return;el.innerHTML=(list||[]).length?(list||[]).map((e,i)=>'<div class="routineItem"><div><b>'+(i+1)+'. '+escapeHtml(e.name)+'</b><small>'+escapeHtml(e.category||e.group||'맨몸')+' · '+e.sets+'세트 × '+e.reps+'회 · 휴식 '+e.rest+'초</small></div>'+(removable?'<button class="btn danger removeCustomExercise" data-i="'+i+'">×</button>':'')+'</div>').join(''):'<div class="empty" style="padding:14px">등록된 운동이 없습니다.</div>';if(removable)$$('.removeCustomExercise').forEach(b=>b.onclick=async()=>{state.workoutConfig.customRoutine.splice(Number(b.dataset.i),1);state.workoutConfig.routineVersion++;await saveState();renderWorkoutBuilder()})}
function renderWorkoutBuilder(){if(!state?.workoutConfig)return;const c=state.workoutConfig,p=intensityProfiles[c.intensity]||intensityProfiles.normal;$('#workoutIntensity').value=c.intensity;$('#workoutTargetMinutes').textContent=p.targetMinutes+'분';$('#workoutEstimate').textContent=c.mode==='auto'&&c.autoEstimatedMinutes?'예상 '+c.autoEstimatedMinutes.toFixed(1)+'분':'25~30분';$('#bodyweightCount').textContent=bodyweightLibrary.length>=50?'홈트 운동 '+bodyweightLibrary.length+'종':'홈트 운동 '+bodyweightLibrary.length+'종 · 로컬 기본 데이터 사용';$$('.modeBtn').forEach(b=>b.classList.toggle('active',b.dataset.workoutMode===c.mode));const select=$('#bodyweightExerciseSelect');const current=select.value;if(bodyweightLibrary.length){select.innerHTML='<option value="">홈트 운동 선택 ('+bodyweightLibrary.length+'종)</option>'+bodyweightLibrary.map(e=>'<option value="'+escapeHtml(e.id)+'">'+escapeHtml(e.name)+' · '+escapeHtml(e.category||'body weight')+'</option>').join('');if(bodyweightLibrary.some(e=>e.id===current))select.value=current}else select.innerHTML='<option value="">홈트 운동 데이터를 불러오지 못했습니다.</option>';renderRoutineItems('#customWorkoutList',c.customRoutine,true);renderRoutineItems('#autoWorkoutList',c.autoRoutine,false);$('#customWorkoutList').style.display=c.mode==='auto'?'none':'grid';$('#autoWorkoutList').style.display=c.mode==='auto'?'grid':'none';$('#routineSummary').textContent=c.mode==='auto'?'자동 루틴 '+c.autoRoutine.length+'종 · '+c.intensity+' · 목표 '+p.targetMinutes+'분':(c.mode==='custom'?'사용자 루틴 '+c.customRoutine.length+'종 · 목표 '+p.targetMinutes+'분':'기본 루틴 사용 중')}
async function setWorkoutMode(mode){ensureWorkoutConfig();if(mode==='custom'&&!state.workoutConfig.customRoutine.length){alert('맨몸 운동을 먼저 추가해 주세요.');return}if(mode==='auto'&&!state.workoutConfig.autoRoutine.length){await generateAutoRoutine();return}state.workoutConfig.mode=mode;state.workoutConfig.routineVersion++;await saveState();renderWorkoutBuilder();prepareWorkout(false)}
async function generateAutoRoutine(){ensureWorkoutConfig();const intensity=$('#workoutIntensity').value||state.workoutConfig.intensity||'normal';state.workoutConfig.intensity=intensity;const p=intensityProfiles[intensity]||intensityProfiles.normal;state.workoutConfig.targetMinutes=p.targetMinutes;$('#autoGenerateWorkout').disabled=true;$('#autoGenerateWorkout').textContent='생성 중...';try{const plan=generateAutoWorkoutLocal(bodyweightLibrary,intensity,localDate()+':'+Date.now());if(!Array.isArray(plan.exercises)||plan.exercises.length<6)throw new Error('사용 가능한 홈트 운동 데이터가 부족합니다. 다시 시도해 주세요.');if(plan.estimatedMinutes<25||plan.estimatedMinutes>30)throw new Error('자동 루틴 시간이 25~30분 범위를 벗어났습니다.');state.workoutConfig.autoRoutine=plan.exercises;state.workoutConfig.autoEstimatedMinutes=Number(plan.estimatedMinutes||0);state.workoutConfig.targetMinutes=Number(plan.targetMinutes||p.targetMinutes);state.workoutConfig.mode='auto';state.workoutConfig.routineVersion++;await saveState();renderWorkoutBuilder();prepareWorkout(false)}catch(e){alert(e.message)}finally{$('#autoGenerateWorkout').disabled=false;$('#autoGenerateWorkout').textContent='루틴 생성'}}
function renderSettings(){const dayNames=['일','월','화','수','목','금','토'];const activeTheme=state.settings?.theme||'mint';$('#themePalette').innerHTML=themePresets.map(t=>'<button class="themeChoice '+(t.id===activeTheme?'active':'')+'" data-theme="'+t.id+'"><span class="themeSwatch" style="background:'+t.soft+'"></span>'+t.name+'</button>').join('');$$('.themeChoice').forEach(b=>b.onclick=async()=>{state.settings.theme=b.dataset.theme;applyTheme(state.settings.theme);await saveState();renderSettings()});$('#settingsTasks').innerHTML=state.tasks.map((t,i)=>'<div class="settingRow" data-i="'+i+'"><div><input class="stitle" value="'+escapeHtml(t.title)+'" style="width:100%;border:1px solid #ccd8d5;border-radius:8px;padding:8px"><div style="font-size:11px;color:var(--muted)">'+t.days.map(d=>dayNames[d]).join('·')+'</div></div><input type="time" class="stime" value="'+t.start+'"><select class="snotify"><option value="exact" '+(t.notify==='exact'?'selected':'')+'>정시</option><option value="-5" '+(t.notify==='-5'?'selected':'')+'>5분 전</option><option value="off" '+(t.notify==='off'?'selected':'')+'>알림 없음</option></select><button class="btn danger deleteTask" data-i="'+i+'">×</button></div>').join('');$$('.deleteTask').forEach(b=>b.onclick=()=>deleteTask(Number(b.dataset.i)));$('#motionSettings').innerHTML=Object.entries(motionCatalog).filter(([key])=>key!=='run').map(([key,meta])=>'<div class="motionRow" data-motion="'+key+'"><div class="motionName"><b>'+meta.name+'</b><small class="motionStatus ok">운동 GIF</small></div><div style="grid-column:span 3;font-size:11px;color:var(--muted)">주동근: '+meta.muscles.join(' · ')+' · GIF 실제 반복시간 자동 동기화</div></div>').join('');}
$('#addTask').onclick=()=>{$('#taskForm').style.display=$('#taskForm').style.display==='none'?'block':'none'};
$('#confirmAddTask').onclick=async()=>{const title=$('#newTitle').value.trim();const days=$$('.newDay:checked').map(x=>Number(x.value));if(!title||!days.length){alert('할 일 이름과 반복요일을 선택해 주세요.');return}state.tasks.push({id:'custom-'+Date.now(),title,start:$('#newStart').value,end:$('#newEnd').value,days,category:$('#newCategory').value,notify:$('#newNotify').value});$('#newTitle').value='';$('#taskForm').style.display='none';await saveState();renderAll()};
async function deleteTask(i){if(!confirm('이 할 일을 삭제하시겠습니까?'))return;state.tasks.splice(i,1);await saveState();renderAll()}
$$('.modeBtn').forEach(b=>b.onclick=()=>setWorkoutMode(b.dataset.workoutMode));
$('#workoutIntensity').onchange=async()=>{ensureWorkoutConfig();state.workoutConfig.intensity=$('#workoutIntensity').value;state.workoutConfig.targetMinutes=(intensityProfiles[state.workoutConfig.intensity]||intensityProfiles.normal).targetMinutes;await saveState();renderWorkoutBuilder();await generateAutoRoutine()};
$('#autoGenerateWorkout').onclick=()=>generateAutoRoutine();
$('#addBodyweightExercise').onclick=async()=>{ensureWorkoutConfig();const id=$('#bodyweightExerciseSelect').value,ex=bodyweightLibrary.find(x=>x.id===id);if(!ex)return;if(state.workoutConfig.customRoutine.some(x=>x.id===id)){alert('이미 사용자 루틴에 포함된 운동입니다.');return}state.workoutConfig.customRoutine.push(exerciseForIntensity(ex,state.workoutConfig.intensity));state.workoutConfig.mode='custom';state.workoutConfig.routineVersion++;await saveState();renderWorkoutBuilder()};
$('#applyCustomWorkout').onclick=async()=>{ensureWorkoutConfig();if(!state.workoutConfig.customRoutine.length){alert('맨몸 운동을 1개 이상 추가해 주세요.');return}state.workoutConfig.customRoutine=state.workoutConfig.customRoutine.map(e=>exerciseForIntensity(e,state.workoutConfig.intensity));state.workoutConfig.mode='custom';state.workoutConfig.routineVersion++;await saveState();renderWorkoutBuilder();prepareWorkout(false)};
$('#refreshBtn').onclick=()=>location.reload();
function renderAll(){renderToday();renderWeek();renderHistory();renderSettings();renderWorkoutBuilder()}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function initPushStatus(){if('serviceWorker'in navigator){try{await navigator.serviceWorker.register('./service-worker.js?v=152',{updateViaCache:'none'});}catch(e){console.warn('service worker',e)}}if(!('Notification'in window)){pushText(false,'이 브라우저는 알림을 지원하지 않습니다.');return}pushText(Notification.permission==='granted',Notification.permission==='granted'?'로컬 알림 활성화됨':'로컬 알림 미설정')}
function pushText(ok,text){const el=$('#pushStatus');if(el)el.innerHTML='<span class="statusDot '+(ok?'ok':'bad')+'"></span>'+text;const mini=$('#pushMini');if(mini)mini.textContent=ok?'LOCAL ON':'LOCAL OFF'}
async function showLocalNotification(title,body,url='./?view=today'){if(!('Notification'in window)||Notification.permission!=='granted')return false;try{if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.ready;await reg.showNotification(title,{body,icon:'./icon-192.png',badge:'./icon-192.png',data:{url}});return true}new Notification(title,{body,icon:'./icon-192.png'});return true}catch(e){console.warn('notification',e);return false}}
function localTimeParts(){const fmt=new Intl.DateTimeFormat('en-GB',{timeZone:state?.settings?.timezone||'Asia/Seoul',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const parts=Object.fromEntries(fmt.formatToParts(new Date()).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));const dayMap={Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6};return {weekday:dayMap[parts.weekday],hhmm:parts.hour+':'+parts.minute}}
function shiftHHMM(hhmm,delta){const [h,m]=String(hhmm).split(':').map(Number);const total=((h*60+m+delta)%1440+1440)%1440;return String(Math.floor(total/60)).padStart(2,'0')+':'+String(total%60).padStart(2,'0')}
async function checkLocalNotifications(){if(!state||Notification.permission!=='granted')return;const p=localTimeParts(),date=localDate();for(const task of state.tasks||[]){if(task.notify==='off'||!task.days?.includes(p.weekday))continue;const due=task.notify==='-5'?shiftHHMM(task.start,-5):task.start;if(due!==p.hhmm)continue;const key='burning-routine-notified:'+date+':'+task.id+':'+due;if(sessionStorage.getItem(key))continue;sessionStorage.setItem(key,'1');await showLocalNotification(task.title||'BURNING ROUTINE',task.notify==='-5'?'5분 후 예정입니다.':'지금 시작할 시간입니다.',task.category==='workout'?'./?view=workout':'./?view=today')}}
function startLocalNotificationWatcher(){checkLocalNotifications();setInterval(checkLocalNotifications,30000)}
$('#enablePush').onclick=async()=>{try{if(!('Notification'in window))throw new Error('이 브라우저는 알림을 지원하지 않습니다.');const perm=await Notification.requestPermission();if(perm!=='granted')throw new Error('알림 권한이 허용되지 않았습니다.');state.settings.pushEnabled=true;await saveState();pushText(true,'로컬 알림 활성화됨')}catch(e){alert(e.message);pushText(false,'로컬 알림 설정 실패')}};
$('#testPush').onclick=async()=>{const ok=await showLocalNotification('BURNING ROUTINE','로컬 알림 테스트입니다.');alert(ok?'테스트 알림을 표시했습니다.':'먼저 로컬 알림을 활성화해 주세요.')};
function handleDeepLink(){const q=new URLSearchParams(location.search);if(q.get('view')==='workout'){switchView('workout');prepareWorkout(true)}}
function todayWorkoutKey(){return weekdayKeys[new Date().getDay()]}
function workoutTaskId(){return new Date().getDay()===6?'saturday-run':'workout-weekday'}
function activeWorkoutLibrary(){ensureWorkoutConfig();const c=state.workoutConfig,p=intensityProfiles[c.intensity]||intensityProfiles.normal;if(c.mode==='auto'&&c.autoRoutine.length)return {key:'auto',title:'자동 '+c.intensity,targetMinutes:p.targetMinutes,exercises:c.autoRoutine};if(c.mode==='custom'&&c.customRoutine.length)return {key:'custom',title:'사용자 루틴',targetMinutes:p.targetMinutes,exercises:c.customRoutine};return workoutLibrary[todayWorkoutKey()]||null}
function getPlanSnapshot(lib){if(!lib)return null;const key=todayWorkoutKey(),wk=weekKey(),c=state.workoutConfig||{mode:'default',routineVersion:0};const snapKey=c.mode==='default'?wk+':'+key:wk+':'+key+':'+c.mode+':'+c.routineVersion;if(!state.workoutPlans[snapKey]){state.workoutPlans[snapKey]={key:snapKey,workoutKey:key,week:wk,completed:false,plan:buildClientPlan(lib.exercises,state.progression||{})};saveState()}return state.workoutPlans[snapKey]}
function buildClientPlan(base,prog){return base.map(ex=>{const level=Math.max(0,Number(prog[ex.id]||0)),max=Number(ex.maxReps||ex.reps+8),raw=Number(ex.reps)+(level*2),reps=Math.min(max,raw),overflow=Math.max(0,Math.ceil((raw-max)/2)),sets=Math.min(5,Number(ex.sets)+overflow),tempo=level>=6?'slow':(ex.tempo||'normal'),durationMinutes=ex.durationMinutes?Math.min(60,ex.durationMinutes+level*5):undefined;return {...ex,reps,sets,tempo,level,durationMinutes}})}
function flattenPlan(plan){const out=[];plan.forEach(ex=>{for(let s=1;s<=ex.sets;s++)out.push({exercise:ex,set:s,totalSets:ex.sets})});return out}
function prepareWorkout(auto=false){if(session?.timer)clearInterval(session.timer);const key=todayWorkoutKey(),lib=activeWorkoutLibrary();stopMotionLoop();if(session?.motion?.blobUrl){try{URL.revokeObjectURL(session.motion.blobUrl)}catch(_){}}if(!lib){$('#workoutDayLabel').textContent='오늘은 휴식일입니다.';$('#woExercise').textContent='회복';$('#woCue').textContent='가벼운 스트레칭과 충분한 수면에 집중합니다.';showMotionMessage('오늘은 휴식일입니다.');return}const snap=getPlanSnapshot(lib);session={snap,lib,steps:flattenPlan(snap.plan),index:0,phase:'ready',startedAt:null,paused:false,pauseAt:null,totalPaused:0,restEnd:null,timer:null,repCount:0,setGuideComplete:false,motion:null};$('#workoutDayLabel').textContent=weekdayKo[new Date().getDay()]+'요일 · '+lib.title+' · 목표 '+lib.targetMinutes+'분';$('#woPart').textContent=lib.title;showCurrent();$('#startWorkout').disabled=false;$('#startWorkout').textContent='운동 시작';$('#nextWorkout').disabled=true;$('#pauseWorkout').disabled=true;$('#skipRest').style.display='none';$('#restBox').classList.remove('show');if(auto)setTimeout(()=>$('#startWorkout').scrollIntoView({behavior:'smooth',block:'center'}),100)}
function showMotionMessage(text){const box=$('#motionEmpty');$('#motionEmptyText').textContent=text;box.classList.add('show');$('#motionGif').style.visibility='hidden';$('#muscleMapCard').style.visibility='hidden';$('#muscleMapLabel').style.visibility='hidden'}
function hideMotionMessage(){$('#motionEmpty').classList.remove('show');$('#motionGif').style.visibility='visible';$('#muscleMapCard').style.visibility='visible';$('#muscleMapLabel').style.visibility='visible'}
function currentStep(){return session?.steps?.[session.index]||null}
function motionKeyFor(ex){return ex?.animation||''}
function targetCycles(ex){return ex?.durationMinutes?Infinity:Number(ex?.reps||0)*(ex?.eachSide?2:1)}
async function showCurrent(){if(!session||!session.steps.length)return false;const s=currentStep(),e=s.exercise;session.repCount=0;session.setGuideComplete=false;if(session.motion?.blobUrl){try{URL.revokeObjectURL(session.motion.blobUrl)}catch(_){}}session.motion=null;$('#woExercise').textContent=e.name;$('#woCue').textContent=e.cue;$('#woSet').textContent='세트 '+s.set+' / '+s.totalSets;$('#woReps').textContent=e.durationMinutes?e.durationMinutes+'분':e.reps+'회'+(e.eachSide?'/측':'');$('#woTempo').textContent=e.durationMinutes?'체크 완료형':'GIF 실제 동작 동기화';$('#progressDetail').textContent=e.level>0?'현재 자동 증가 단계 +'+e.level:'기본 강도';$('#currentRep').textContent=e.durationMinutes?'시간 운동':'0 / '+e.reps;$('#sideLabel').textContent=e.eachSide?'오른쪽부터':'반복';$('#phaseLabel').textContent='준비';$('#phaseRemain').textContent=e.durationMinutes?'완료 체크':'근성장 GIF 준비';$('#nextWorkout').disabled=true;return loadMotionForCurrent(false)}
function restartExerciseGif(){const img=$('#motionGif'),m=session?.motion;if(!m?.blobUrl)return;img.classList.remove('paused');img.removeAttribute('src');requestAnimationFrame(()=>{img.src=m.blobUrl})}
async function loadMotionForCurrent(autoPlay=false){const step=currentStep();if(!step)return false;const e=step.exercise,key=motionKeyFor(e),localMuscles=(e.muscles?.length?e.muscles:(motionCatalog[key]?.muscles||[]));stopMotionLoop();hideMotionMessage();const img=$('#motionGif'),map=$('#muscleMap'),mapCard=$('#muscleMapCard'),mapLabel=$('#muscleMapLabel');img.classList.remove('motionMirror','paused');$('#motionSourceName').textContent='근성장 GIF 불러오는 중';$('#muscleText').textContent=localMuscles.join(' · ');mapCard.style.display='block';mapLabel.style.display='block';map.onerror=()=>{mapCard.style.display='none';mapLabel.style.display='none'};map.onload=()=>{mapCard.style.display='block';mapLabel.style.display='block'};map.src=muscleMapUrl(key,e);try{let meta;if(e.gifPath){meta={exerciseId:e.exerciseId||e.id,name:e.name,targetMuscles:localMuscles,secondaryMuscles:[],proxyUrl:EXERCISEDB_MIRROR_BASE+e.gifPath}}else{meta=resolveExerciseMediaLocal(key);if(!meta)throw new Error('정확한 근성장 동작 매칭 실패')}const gifResp=await fetch(meta.proxyUrl,{cache:'force-cache'});if(!gifResp.ok)throw new Error('GIF 다운로드 실패');const buf=await gifResp.arrayBuffer();const cycle=parseGifLoopSeconds(buf);const blobUrl=URL.createObjectURL(new Blob([buf],{type:'image/gif'}));session.motion={type:'gif',key:e.id||key,blobUrl,cycleSeconds:cycle,media:meta,lastVisualCycle:-1};$('#motionSourceName').textContent=e.name||meta.name;$('#muscleText').textContent=[...(meta.targetMuscles||[]),...(meta.secondaryMuscles||[]).slice(0,2)].join(' · ')||localMuscles.join(' · ');img.onerror=()=>showMotionMessage('근성장 GIF를 표시하지 못했습니다. 다시 시도해 주세요.');img.src=blobUrl;$('#phaseLabel').textContent='준비';$('#phaseRemain').textContent='1회 '+cycle.toFixed(1)+'초';$('#woTempo').textContent='GIF 1회 '+cycle.toFixed(1)+'초 동기화';if(autoPlay)startMotionLoop();return true}catch(err){console.error(err);session.motion=null;showMotionMessage('근성장 GIF를 불러오지 못했습니다. 네트워크 연결 후 다시 시도해 주세요.');return false}}
function stopMotionLoop(){if(motionRaf){cancelAnimationFrame(motionRaf);motionRaf=null}}
function startMotionLoop(){const step=currentStep(),m=session?.motion;if(!step||!m)return;session.repCount=0;session.setGuideComplete=false;session.motionStartedAt=performance.now();m.lastVisualCycle=-1;restartExerciseGif();stopMotionLoop();const tick=()=>{syncMotionFrame();if(session&&session.phase==='work'&&!session.paused&&!session.setGuideComplete)motionRaf=requestAnimationFrame(tick)};motionRaf=requestAnimationFrame(tick)}
function completeGuideSet(e){session.setGuideComplete=true;stopMotionLoop();$('#phaseLabel').textContent='세트 완료';$('#phaseRemain').textContent='다음을 눌러 휴식';$('#currentRep').textContent=e.reps+' / '+e.reps;$('#sideLabel').textContent=e.eachSide?'양쪽 완료':'완료';$('#nextWorkout').disabled=false}
function syncMotionFrame(){const step=currentStep(),m=session?.motion;if(!step||!m||session.phase!=='work'||session.paused)return;const e=step.exercise;if(e.durationMinutes){$('#phaseLabel').textContent='러닝';$('#phaseRemain').textContent='오늘 목록에서 완료 체크';$('#nextWorkout').disabled=false;return}const cycle=Math.max(.6,Number(m.cycleSeconds)||3),wallElapsed=Math.max(0,(performance.now()-session.motionStartedAt)/1000),completedCycles=Math.floor(wallElapsed/cycle);session.repCount=Math.max(session.repCount,completedCycles);if(completedCycles!==m.lastVisualCycle&&session.repCount<targetCycles(e)){m.lastVisualCycle=completedCycles;if(completedCycles>0)restartExerciseGif()}const inCycle=wallElapsed%cycle,remain=Math.max(0,cycle-inCycle);$('#phaseLabel').textContent='동작 따라하기';$('#phaseRemain').textContent='다음 반복 '+remain.toFixed(1)+'초';const perSide=Number(e.reps||0),cycles=targetCycles(e),displayRep=Math.min(perSide,session.repCount+1-(e.eachSide&&session.repCount>=perSide?perSide:0));$('#currentRep').textContent=Math.max(0,displayRep)+' / '+perSide;const img=$('#motionGif');if(e.eachSide){const left=session.repCount>=perSide;$('#sideLabel').textContent=left?'왼쪽':'오른쪽';img.classList.toggle('motionMirror',left)}else{$('#sideLabel').textContent='반복';img.classList.remove('motionMirror')}if(session.repCount>=cycles)completeGuideSet(e)}
async function runPrepCountdown(){const overlay=$('#prepOverlay'),count=$('#prepCount');overlay.classList.add('show');for(let n=3;n>=1;n--){count.textContent=n;await new Promise(r=>setTimeout(r,1000))}count.textContent='GO';await new Promise(r=>setTimeout(r,350));overlay.classList.remove('show')}
$('#startWorkout').onclick=async()=>{if(!session)prepareWorkout();const ok=session.motion||await loadMotionForCurrent(false);if(!ok)return;$('#startWorkout').disabled=true;$('#pauseWorkout').disabled=true;session.phase='prep';await runPrepCountdown();session.startedAt=Date.now();session.phase='work';session.totalPaused=0;session.paused=false;$('#pauseWorkout').disabled=false;$('#nextWorkout').disabled=false;session.timer=setInterval(tickWorkout,100);startMotionLoop();tickWorkout()};
$('#nextWorkout').onclick=()=>{if(!session||session.phase!=='work'||session.paused)return;if(session.index>=session.steps.length-1){finishWorkout();return}startRest()};
function startRest(){const s=currentStep();stopMotionLoop();session.phase='rest';session.restEnd=Date.now()+s.exercise.rest*1000;$('#restBox').classList.add('show');$('#skipRest').style.display='block';$('#nextWorkout').disabled=true;$('#phaseLabel').textContent='휴식';$('#phaseRemain').textContent=s.exercise.rest+'초';$('#currentRep').textContent='REST';$('#sideLabel').textContent='호흡 정리';$('#motionGif').classList.add('paused')}
async function endRest(){session.index++;session.phase='work';session.restEnd=null;$('#restBox').classList.remove('show');$('#skipRest').style.display='none';$('#nextWorkout').disabled=true;await showCurrent();$('#nextWorkout').disabled=false;if(session.motion)startMotionLoop();if(navigator.vibrate)navigator.vibrate([120,80,120])}
$('#skipRest').onclick=()=>{if(session?.phase==='rest')endRest()};
$('#pauseWorkout').onclick=()=>{if(!session||!session.startedAt||session.phase!=='work')return;if(!session.paused){session.paused=true;session.pauseAt=Date.now();stopMotionLoop();$('#motionGif').classList.add('paused');$('#pauseWorkout').textContent='계속';$('#phaseLabel').textContent='일시정지'}else{const delta=Date.now()-session.pauseAt;session.totalPaused+=delta;session.paused=false;session.pauseAt=null;$('#pauseWorkout').textContent='일시정지';const completed=session.repCount;session.motionStartedAt=performance.now()-completed*(session.motion?.cycleSeconds||3)*1000;restartExerciseGif();if(!session.setGuideComplete){const tick=()=>{syncMotionFrame();if(session&&session.phase==='work'&&!session.paused&&!session.setGuideComplete)motionRaf=requestAnimationFrame(tick)};motionRaf=requestAnimationFrame(tick)}}};
function fmt(sec){sec=Math.max(0,Math.floor(sec));return pad(Math.floor(sec/60))+':'+pad(sec%60)}
function tickWorkout(){if(!session?.startedAt||session.paused)return;const elapsed=(Date.now()-session.startedAt-session.totalPaused)/1000;$('#elapsed').textContent=fmt(elapsed);const target=(session.lib.targetMinutes||25)*60;$('#remain').textContent=elapsed<=target?fmt(target-elapsed):'+'+fmt(elapsed-target);if(session.phase==='rest'){const left=Math.max(0,Math.ceil((session.restEnd-Date.now())/1000));$('#restSec').textContent=left;$('#phaseRemain').textContent=left+'초';if(left<=0)endRest()}}
async function finishWorkout(){stopMotionLoop();clearInterval(session.timer);if(session?.motion?.blobUrl){try{URL.revokeObjectURL(session.motion.blobUrl)}catch(_){}}const snap=session.snap;if(!snap.completed){snap.completed=true;snap.completedAt=new Date().toISOString();snap.plan.forEach(e=>state.progression[e.id]=Number(state.progression[e.id]||0)+1);const date=localDate();state.completions[date]=state.completions[date]||{};state.completions[date][workoutTaskId()]=true;state.history.unshift({type:'workout',title:session.lib.title+' 운동 완료',date,at:new Date().toISOString(),week:snap.week});await saveState()}session.phase='done';$('#woExercise').textContent='운동 완료';$('#woCue').textContent='오늘 루틴을 모두 완료했습니다. 다음 주 같은 운동은 자동으로 한 단계 증가합니다.';$('#woSet').textContent='완료';$('#woReps').textContent='전주 완료 ✓';$('#woTempo').textContent='다음 주 자동 증가';$('#phaseLabel').textContent='완료';$('#phaseRemain').textContent='운동 종료';$('#currentRep').textContent='✓';$('#sideLabel').textContent='완료';$('#nextWorkout').disabled=true;$('#pauseWorkout').disabled=true;$('#restBox').classList.remove('show');$('#skipRest').style.display='none';renderToday();renderHistory();if(navigator.vibrate)navigator.vibrate([150,80,150,80,250])}
const openMotionSettings=$('#openMotionSettings');if(openMotionSettings)openMotionSettings.onclick=()=>{switchView('settings');setTimeout(()=>$('#motionSettings').scrollIntoView({behavior:'smooth',block:'start'}),100)};
$('#motionRetry').onclick=async()=>{hideMotionMessage();if(session?.motion?.blobUrl){restartExerciseGif();if(session.paused){if(session.pauseAt)session.totalPaused+=Date.now()-session.pauseAt;session.paused=false;session.pauseAt=null;$('#pauseWorkout').textContent='일시정지'}if(session.phase==='work'&&!session.setGuideComplete){session.motionStartedAt=performance.now()-session.repCount*(session.motion.cycleSeconds||3)*1000;stopMotionLoop();const tick=()=>{syncMotionFrame();if(session&&session.phase==='work'&&!session.paused&&!session.setGuideComplete)motionRaf=requestAnimationFrame(tick)};motionRaf=requestAnimationFrame(tick)}}else showCurrent()};
load().catch(e=>{console.error(e);const msg=String(e?.message||e||'알 수 없는 오류');document.body.insertAdjacentHTML('beforeend','<div style="position:fixed;bottom:10px;left:10px;right:10px;background:#8b1e1e;color:white;padding:12px;border-radius:10px;z-index:9999">앱 초기화 오류: '+escapeHtml(msg)+'</div>')});
